<?php require __DIR__.'/bootstrap.php'; $err=''; if(ready()){http_response_code(403);exit('Đã cài đặt. Xóa setup.php khỏi hosting.');} if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{if(!is_file(__DIR__.'/config.php')||!db())throw new Exception('Cần cấu hình MySQL trước.');$c=require __DIR__.'/config.php';if(strlen($c['setup_key'])<24||str_contains($c['setup_key'],'CHANGE')||!hash_equals($c['setup_key'],(string)($_POST['key']??'')))throw new Exception('Setup key không hợp lệ.');$u=trim($_POST['username']??'');$pw=$_POST['password']??'';if(strlen($u)<3||strlen($u)>100||strlen($pw)<12)throw new Exception('Tên đăng nhập 3–100 ký tự, mật khẩu ít nhất 12 ký tự.');foreach(explode(';',file_get_contents(__DIR__.'/schema.sql')) as $sql)if(trim($sql))db()->exec($sql);if(ready())throw new Exception('Đã cài đặt.');$q=db()->prepare('INSERT INTO admins(username,password_hash) VALUES (?,?)');$q->execute([$u,password_hash($pw,PASSWORD_DEFAULT)]);redirect('admin.php');}catch(Throwable $x){$err=$x instanceof PDOException?'Lỗi cơ sở dữ liệu.':$x->getMessage();}}
?><!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/style.css"><title>Cài đặt</title><body><main class="login panel"><h1>Cài đặt Wedding</h1><p><?=e($err)?></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Setup key<input name="key" type="password" required></label><label>Tên đăng nhập<input name="username" required></label><label>Mật khẩu<input name="password" type="password" minlength="12" required></label><button>Cài đặt</button></form></main></body></html>
